head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05400";
scwin.form = null;
scwin.w = '600';
scwin.h = '520';
scwin.corpNoWin = null;
scwin.l = undefined;
scwin.t = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((dma_pageContext.get("isurCd") ?? "")); } },
        { childId: "ipt_empNm", fn: function () { return String((dma_pageContext.get("empNm") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.ListedNotifyForm || { elements: [] });
        $c.util.getComponent("rd_searchGubun").setValue("1");
        $c.util.getComponent("rd_searchGubun").setValue("2");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05400.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05400' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil05400: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.l =screen.width/2 - scwin.w/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05400' }); }

try { scwin.t =screen.height/2 - scwin.h/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05400' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05400.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_OpenCorpNoCodeWin_onclick
 * @description btn_OpenCorpNoCodeWin 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_OpenCorpNoCodeWin_onclick = async function(e){
    try {
        await scwin.openCorpNoCodeWin()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05400.btn_OpenCorpNoCodeWin_onclick' }); }
};

/**
 * @method
 * @name rd_searchGubun_onclick
 * @description 「1」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_searchGubun_onclick = function(e){
    try {
        scwin.checkValue()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05400.rd_searchGubun_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05400.btn_Search_onclick' }); }
};

/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05400.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchDetail(r["listDtlNotiId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/list/listNotify.do",
        ref: "dma_SearchDetailReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function (action) {
    const sbmOptions = {
        id: "tx_fn_SearchDetail",
        method: "post",
        action: action ?? "/list/listNotify.do",
        ref: "dma_SearchDetailReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const startDate = (document.ListedNotifyForm || { elements: [] }).startDate.value;
    const endDate = $c.util.getComponent('cal_endDate').getValue();
    if (parseInt((document.ListedNotifyForm || { elements: [] }).startDate.value, '10') > parseInt($c.util.getComponent('cal_endDate').getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        (document.ListedNotifyForm || { elements: [] }).startDate.value = startDate;
        $c.util.getComponent("cal_endDate").setValue(endDate);
        return false;
    }
    $c.util.getComponent('dma_SearchDetailReq').set('comNm', $c.util.getComponent('ipt_isurCd').getValue());
    $c.util.getComponent('dma_SearchDetailReq').set('method', 'listListNotify');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} listDtlNotiId listDtlNotiId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (listDtlNotiId) {
    $c.util.getComponent('dma_SearchDetailReq').set('listDtlNotiId', listDtlNotiId);
    $c.util.getComponent('dma_SearchDetailReq').set('method', 'searchListNotify');
    const nr = await scwin.tx_fn_SearchDetail('/list/listNotify.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL05401.xml", { "listDtlNotiId": listDtlNotiId, "method": 'searchListNotify' });
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkValue = function () {
    $c.util.getComponent('dma_SearchDetailReq').set('searchGubun1', $c.util.getComponent('rd_searchGubun').getValue());
};

/**
 * @method
 * @name openCorpNoCodeWin
 * @description open Corp No Code Win 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openCorpNoCodeWin = async function () {
    if (scwin.corpNoWin != null) {
        if (!scwin.corpNoWin.closed) {
            scwin.corpNoWin.close();
        }
    }
    scwin.corpNoWin = scwin.setCorpInfo_recv(await $c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp", width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { corpNoWin: (typeof scwin.corpNoWin !== 'undefined' ? scwin.corpNoWin : undefined) })));
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent("ipt_isurCd").setValue(comNm);
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };

/**
 * @method
 * @name krxpage_pagenavigator_100_onclick
 * @description krxpage_pagenavigator_100 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_100_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchDetailReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05400.krxpage_pagenavigator_100_onclick" });
    }
};
